const suites=[];
let currentSuite=null;

export function describe(name,fn){
  const suite={name,tests:[]};
  suites.push(suite);
  const prev=currentSuite;currentSuite=suite;
  try{fn();}finally{currentSuite=prev;}
}
export function it(name,fn){
  if(!currentSuite)throw new Error("it() måste ligga i describe()");
  currentSuite.tests.push({name,fn});
}
function fail(message){throw new Error(message);}
export const assert={
  equal(actual,expected,message=""){if(!Object.is(actual,expected))fail(message||`Förväntade ${String(expected)}, fick ${String(actual)}`);},
  notEqual(actual,expected,message=""){if(Object.is(actual,expected))fail(message||`Värdena skulle vara olika men båda var ${String(actual)}`);},
  true(value,message=""){if(value!==true)fail(message||`Förväntade true, fick ${String(value)}`);},
  false(value,message=""){if(value!==false)fail(message||`Förväntade false, fick ${String(value)}`);},
  throws(fn,message=""){let threw=false;try{fn();}catch{threw=true;}if(!threw)fail(message||"Förväntade att funktionen skulle kasta ett fel.");}
};
function esc(s){return String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}
export const teevi={
  async run(){
    const host=document.getElementById("teevi-results");
    let pass=0,failCount=0;
    const rows=[];
    for(const suite of suites){
      rows.push(`<h2>${esc(suite.name)}</h2>`);
      for(const test of suite.tests){
        try{
          const result=test.fn();
          if(result&&typeof result.then==="function")await result;
          pass++;rows.push(`<div class="test pass">✓ ${esc(test.name)}</div>`);
        }catch(error){
          failCount++;rows.push(`<div class="test fail">✗ ${esc(test.name)}<pre>${esc(error?.stack||error)}</pre></div>`);
        }
      }
    }
    const total=pass+failCount;
    const summary=`<div class="summary ${failCount?"bad":"good"}"><strong>${pass}/${total} godkända</strong>${failCount?` · ${failCount} fel`:" · alla tester godkända"}</div>`;
    if(host)host.innerHTML=summary+rows.join("");
    document.title=`${failCount?"FAIL":"PASS"} · cm-chessboard test`;
    return {pass,fail:failCount,total};
  }
};
